import {esc,fmt,num} from './render.js';
const controlMetrics=[['starts_per_h','시간당 새 지속 단절','회 / 시간'],['cut_s_per_h','시간당 지속 단절 시간','초 / 시간'],['timely_pdr','0.25초 내 전달률','ratio'],['mean_relay_m','평균 중계기 이동 거리','m']];
const forecastMetrics=[['recall','선행 탐지율','ratio'],['precision','경보 정밀도','ratio'],['false_per_h','오경보·늦은 경보','회 / 편대·시간'],['average_precision','평균 정밀도 (AP)','ratio']];
function metrics(values,definitions){return '<div class="summary-metrics">'+definitions.map(([key,label,unit])=>'<div class="summary-value" data-metric="'+key+'"><span>'+esc(label)+'</span><strong>'+esc(fmt(values[key],unit,2))+'</strong></div>').join('')+'</div>'}
export function renderFinalSummary(model){
 if(model?.status!=='available')return '<div class="notice">현재 코어의 출처와 평가 자료가 제공되지 않았습니다.</div>';
 const control=model.supplied_evaluation?.control,forecast=model.supplied_evaluation?.forecast,evidence=model.source_refs||[];
 return '<p class="summary-policy">현재 지도 비행은 11월 13일 시뮬레이터의 예측 모델과 추가 복구 재배치 규칙을 함께 사용합니다. 제공된 학습 가중치를 그대로 사용하며 재학습하지 않았습니다.</p>'+
 '<article class="summary-card final-summary"><div class="summary-heading"><div><span class="tag teal">현재 적용 구성</span><h4>예측 모델 + 복구 재배치 보강</h4></div></div><p>예측·제어: <strong>'+esc(model.controller)+'</strong><br>추가 규칙: <strong>'+esc(model.relocation_variant)+'</strong><br>연구 배포본: '+esc(model.release_date)+'</p><p class="hint">복구 보강은 수색 드론의 비콘 관측 공백으로 기존 판단이 생략될 때 재연결 후보를 검토합니다. 복구 명령이 있다는 것만으로 실제 수색망이 단절됐다고 판정하지 않습니다. 각 지역의 결합 코어 성능은 ‘실험 비교’에서 확인합니다.</p></article>'+
 (control&&forecast?'<div class="summary-grid"><article class="summary-card final-summary"><div class="summary-heading"><div><span class="tag muted">배포본에 포함된 평가</span><h4>11월 13일 모델의 제어 성능</h4></div><span class="tag muted">'+num(control.flights,0)+'개 비행</span></div><p class="summary-description">추가 복구 규칙 적용 전의 저장 평가 · 임무 완료 '+num(control.completed,0)+' / '+num(control.flights,0)+'</p>'+metrics(control,controlMetrics)+'<p class="hint">현재 지도 비행의 집계가 아닙니다. 지속 단절은 수색망이 1초 이상 끊긴 구간입니다. 전달률은 생성 패킷 중 0.25초 안에 전달된 비율이며, 메인 카드의 일반 PDR과 구분합니다.</p></article><article class="summary-card final-summary"><div class="summary-heading"><div><span class="tag muted">배포본에 포함된 평가</span><h4>새 예측 모델의 선행 탐지 성능</h4></div><span class="tag muted">단절 '+num(forecast.events,0)+'건</span></div><p class="summary-description">배포본의 기준 비행 관측 이력에서 계산한 혼합 예측 점수 평가</p>'+metrics(forecast,forecastMetrics)+'<p class="hint">단절 시작보다 3초 이상 7초 미만 앞선 경보를 일대일 대응합니다. 지역별로 새로 실행한 평가와 대상 비행이 달라 수치가 다를 수 있습니다. 이 표는 복구 추가 규칙과 결합한 성능을 증명하는 표가 아닙니다.</p></article></div>':'<p class="hint">제공된 배포본의 모델 평가를 확인할 수 없어 이전 모델의 수치는 표시하지 않았습니다.</p>')+
 '<details class="summary-provenance"><summary>코어와 평가 출처</summary><p>평가 기록 시각: '+esc(model.supplied_evaluation?.completed_at||'미기록')+'</p><ul>'+evidence.map(row=>'<li>'+esc(row.path)+'<br><small>SHA-256 '+esc(row.sha256)+'</small></li>').join('')+'</ul></details>';
}
export function renderSummaryLibrary(data){return renderFinalSummary(data?.new_core)}
